<?php
// Local audit-only fixtures; not shipped or deployed.
if(!in_array(wp_parse_url(home_url(),PHP_URL_HOST),['127.0.0.1','localhost'],true))return;
add_filter('pre_wp_mail',static fn()=>true);
add_filter('pre_http_request',static function($value,$args,$url){if($url!=='https://fixtures.kumo.test/feed/')return $value;return ['response'=>['code'=>200],'headers'=>['content-type'=>'application/rss+xml; charset=UTF-8'],'body'=>'<?xml version="1.0"?><rss version="2.0"><channel><title>Audit fixture feed</title><link>https://fixtures.kumo.test/</link><description>Controlled test feed</description><item><title>A sample feed item with a useful title</title><link>https://fixtures.kumo.test/one</link><guid>kumo-audit-one</guid><description>Short sample content for native RSS widget rendering.</description><pubDate>Sun, 08 Nov 2026 00:00:00 GMT</pubDate></item><item><title>Another native feed item</title><link>https://fixtures.kumo.test/two</link><guid>kumo-audit-two</guid><description>A second summary to check spacing.</description><pubDate>Sat, 07 Nov 2026 00:00:00 GMT</pubDate></item></channel></rss>'];},10,3);
add_action('init',static function(){if(isset($_GET['kumo-audit-login'])&&in_array($_SERVER['REMOTE_ADDR']??'', ['127.0.0.1','::1'],true)){wp_set_current_user(1);wp_set_auth_cookie(1);wp_safe_redirect(home_url('/'));exit;}});
add_shortcode('kumo_audit_widgets',static function(){
 $m=get_option('_kumo_visual_audit_manifest',[]);$html='<div class="kumo-audit-widget-grid">';
 foreach($m['sidebar_widgets']??[] as $id){$split=strrpos($id,'-');$base=substr($id,0,$split);$number=(int)substr($id,$split+1);$class='';foreach($GLOBALS['wp_widget_factory']->widgets as $candidate=>$widget){if($widget->id_base===$base){$class=$candidate;break;}}if(!$class)continue;$config=get_option('widget_'.$base)[$number]??[];ob_start();the_widget($class,$config,['widget_id'=>wp_unique_id('kva-'),'before_widget'=>'<section class="kh-widget widget_'.$base.'" data-native-widget="'.esc_attr($class).'">','after_widget'=>'</section>','before_title'=>'<h2 class="kh-widget-title">','after_title'=>'</h2>']);$html.='<div class="kumo-audit-widget-case"><p class="kumo-audit-label">'.esc_html($class).' · 280px</p><div class="kh-sidebar">'.ob_get_clean().'</div></div>';}
 return $html.'</div>';
});
add_action('wp_enqueue_scripts',static function(){wp_add_inline_style('kumo-hybrid-style','.kumo-audit-widget-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),280px));gap:2rem;align-items:start}.kumo-audit-widget-case{min-width:0}.kumo-audit-label{font:500 .75rem/1.4 var(--kh-sans);margin:0 0 1rem}.kumo-audit-widget-case>.kh-sidebar{margin-block-start:0}');},20);
add_filter('pre_get_avatar_data',static function($args){$m=get_option('_kumo_visual_audit_manifest');if(!empty($m['media']['image'])){$args['url']=wp_get_attachment_image_url($m['media']['image'],'thumbnail');$args['found_avatar']=true;}return $args;});
add_action('template_redirect',static function(){
 if(!isset($_GET['kumo-widget-case']))return;
 $id=sanitize_key(wp_unslash($_GET['kumo-widget-case']));$m=get_option('_kumo_visual_audit_manifest',[]);if(!in_array($id,$m['sidebar_widgets']??[],true)){status_header(404);exit;}
 $width=max(200,min(480,absint($_GET['width']??280)));$split=strrpos($id,'-');$base=substr($id,0,$split);$number=(int)substr($id,$split+1);$class='';foreach($GLOBALS['wp_widget_factory']->widgets as $name=>$widget){if($widget->id_base===$base){$class=$name;break;}}
 get_header();echo '<main id="main" class="kh-main kh-shell"><div class="kh-sidebar" style="width:'.esc_attr($width).'px" data-audit-width="'.esc_attr($width).'">';the_widget($class,get_option('widget_'.$base)[$number]??[],['widget_id'=>wp_unique_id('case-'),'before_widget'=>'<section class="kh-widget widget_'.$base.'" data-native-widget="'.esc_attr($class).'">','after_widget'=>'</section>','before_title'=>'<h2 class="kh-widget-title">','after_title'=>'</h2>']);echo '</div></main>';get_footer();exit;
});
add_shortcode('kumo_audit_icons',static function(){if(!function_exists('kumo_hybrid_icon'))return ''; $html='<div class="kumo-audit-icon-grid">';foreach(['menu','mode','sun','arrow','chevron','search','check','rss','comment','reply','close'] as $role){$html.='<div>'.kumo_hybrid_icon($role).'<span>'.esc_html($role).'</span></div>';}return $html.'</div>';});
add_action('wp_enqueue_scripts',static function(){wp_add_inline_style('kumo-hybrid-style','.kumo-audit-icon-grid{display:flex;flex-wrap:wrap;gap:1.5rem}.kumo-audit-icon-grid>div{display:flex;align-items:center;gap:.5rem}');},25);
